<?php
require_once __DIR__ . '/auth.php';
require_login();

$flash = $_SESSION['flash_message'] ?? '';
unset($_SESSION['flash_message']);
$produkResult = mysqli_query($koneksi, 'SELECT id_produk, nama_produk, harga, stok, deskripsi, foto FROM produk ORDER BY id_produk DESC');
if (!$produkResult) {
    http_response_code(500);
    exit('Data produk tidak dapat dimuat. Pastikan tabel produk sudah dibuat.');
}
$summaryResult = mysqli_query($koneksi, 'SELECT COUNT(*) AS total_produk, COALESCE(SUM(stok), 0) AS total_stok, COALESCE(SUM(stok <= 5), 0) AS stok_menipis FROM produk');
$summary = mysqli_fetch_assoc($summaryResult);
?>
