<section class="data"><div class="datahead"><div><h2>Data Komoditas</h2><div class="caption">Daftar produk dari database.</div></div><a class="btn primary" href="tambah.php">＋ Tambah Produk</a></div><?php if ($flash !== ''): ?><div class="alert" role="status"><?= h($flash) ?></div><?php endif; ?><div class="scroll"><table><thead><tr><th>No</th><th>Nama Produk</th><th>Foto</th><th>Harga (Rp)</th><th>Stok</th><th>Aksi</th></tr></thead><tbody><?php if (mysqli_num_rows($produkResult) > 0): ?><?php $nomor = 1; while ($produk = mysqli_fetch_assoc($produkResult)): ?><tr><td><?= $nomor++ ?></td><td><div class="product"><?= h($produk['nama_produk']) ?></div><div class="desc"><?= h($produk['deskripsi']) ?></div></td><td><?php if (!empty($produk['foto'])): ?><img class="thumb" src="assets/images/<?= h(basename($produk['foto'])) ?>" alt="Foto <?= h($produk['nama_produk']) ?>"><?php else: ?><span class="thumb" aria-label="Tidak ada foto"></span><?php endif; ?></td><td class="price"><?= number_format((int) $produk['harga'], 0, ',', '.') ?></td><td><span class="stock"><?= number_format((int) $produk['stok']) ?></span></td><td><div class="rowactions"><a class="edit" href="edit.php?id=<?= (int) $produk['id_produk'] ?>">Edit</a><form method="post" action="hapus.php" onsubmit="return confirm('Hapus produk ini?');"><input type="hidden" name="csrf_token" value="<?= h(csrf_token()) ?>"><input type="hidden" name="id_produk" value="<?= (int) $produk['id_produk'] ?>"><button class="delete" type="submit">Hapus</button></form></div></td></tr><?php endwhile; ?><?php else: ?><tr><td class="empty" colspan="6">Belum ada produk. Klik “Tambah Produk” untuk memulai.</td></tr><?php endif; ?></tbody></table></div><div class="footnote">Data inventori diperbarui langsung dari tabel <code>produk</code>.</div></section></main></body></html>